describe('Locked-Out Customer Login Error Message', () => {
  beforeEach(() => {
    cy.visit('/login');
  });

  it('should display error message when logging in with locked-out user credentials', () => {
    cy.get('[data-testid="username-input"]').type('locked_out_user');
    cy.get('[data-testid="password-input"]').type('secret_sauce');
    cy.get('[data-testid="login-button"]').click();

    cy.get('[data-testid="error-container"]').should('be.visible');
    cy.get('[data-testid="error-container"]').should('contain', 'Sorry, this user has been locked out');
    cy.get('[data-testid="error-container"]').should('have.class', 'error-message');
    cy.get('[data-testid="error-container"]').should('have.text', 'Sorry, this user has been locked out');
    cy.get('[data-testid="error-container"]').should('be.visible');
    cy.get('[data-testid="error-container"]').should('contain', 'Please contact support');
    cy.get('[data-testid="error-container"]').should('contain', 'to reset your account');
  });

  it('should not display error message when logging in with valid credentials', () => {
    cy.get('[data-testid="username-input"]').type('valid_user');
    cy.get('[data-testid="password-input"]').type('correct_password');
    cy.get('[data-testid="login-button"]').click();

    cy.get('[data-testid="error-container"]').should('not.exist');
    cy.url().should('include', '/dashboard');
    cy.get('[data-testid="welcome-message"]').should('be.visible');
    cy.get('[data-testid="welcome-message"]').should('contain', 'Welcome back');
  });
});
